import hashlib,json,os,random,resource,signal,subprocess,sys
from pathlib import Path
sys.path.insert(0,str(Path('tests/intinf').resolve()))
import run as corpus
out=Path('tests/out/intinf/optimization/final4/extra');out.mkdir(exist_ok=True)
rng=random.Random(0x50415448);pairs=[]
for bits in [15,30,31,32,61,62,63,64,65,120,128,255,512,1024]:
 for delta in [-1,0,1]:
  for sign in [-1,1]:
   a=sign*((1<<bits)+delta)
   for b in [1,-1,255,-255,(1<<62)-1,-(1<<62)]:pairs.append((a,b))
for _ in range(100):
 a=rng.getrandbits(rng.choice([30,63,64,128,256,1024,4096]))*rng.choice([-1,1])
 b=(rng.getrandbits(rng.choice([15,62,128,512,4096])) or 1)*rng.choice([-1,1]);pairs.append((a,b))
for bits in [63,64,128,256,1024,4096]:
 a=(1<<bits)-1
 for delta in [-1,0,1]:pairs.append((a,-a+delta))
rows=[]
for a,b in pairs:
 q=abs(a)//abs(b)*(-1 if (a<0)!=(b<0) else 1)
 values=[a+b,a-b,a*b,a//b,a%b,q,a-q*b,a&b,a|b,a^b,~a,a<<31,a>>31]
 rows.append('('+','.join([json.dumps(corpus.sml(a)),json.dumps(corpus.sml(b)),'['+','.join(json.dumps(corpus.sml(v)) for v in values)+']'])+')')
source=out/'vectors.sml';source.write_text('structure IntInfVectors = struct\nval cases = [\n'+',\n'.join(rows)+'\n]\nend\n')
commands=[]
def run(command,label):
 commands.append(command)
 def limit():
  resource.setrlimit(resource.RLIMIT_CORE,(0,0));resource.setrlimit(resource.RLIMIT_AS,(4*1024**3,4*1024**3))
 p=subprocess.Popen(command,stdout=subprocess.PIPE,stderr=subprocess.PIPE,start_new_session=True,preexec_fn=limit)
 try:stdout,stderr=p.communicate(timeout=180)
 except BaseException:
  os.killpg(p.pid,signal.SIGKILL);p.communicate();raise
 (out/(label+'.stdout')).write_bytes(stdout);(out/(label+'.stderr')).write_bytes(stderr)
 assert p.returncode==0,(command,stderr.decode())
 return stdout.decode()
rbc=out/'checks.rbc'
run(['bin/rune','--lib','lib','-o',str(rbc),'tests/intinf/oracle.sml',str(source),'tests/intinf/checks.sml'],'compile')
expected=f'current: {len(pairs)*5+4} checks\noracle: {len(pairs)*5+4} checks\n'
for mode in ['gmp','sml']:
 for jit,opts in [('off',['--jit=off']),('tier2',['--jit=all','--jit-tier=2'])]:
  assert run(['bin/runevm','--intinf='+mode,*opts,str(rbc)],mode+'-'+jit)==expected
sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest()
(out/'report.json').write_text(json.dumps({'seed':0x50415448,'pairs':len(pairs),'checks_per_implementation':len(pairs)*5+4,'result':'pass','commands':commands,'source_sha256':sha(source),'bytecode_sha256':sha(rbc),'driver_sha256':sha(__file__),'vm_sha256':sha('bin/runevm'),'intinf_sha256':sha('lib/basis/intinf.sml')},indent=2)+'\n')
print('PASS expanded independent corpus',len(pairs)*5+4,'checks per implementation, both backends and interpreter/tier2')
